import React, { useState, useEffect, useCallback } from 'react';
import {
  listarGarcons, criarGarcom, atualizarGarcom, removerGarcom,
  listarMesas, criarMesa, removerMesa, criarMesasEmLote,
} from '../../services/restauranteService';
import Icon from '../../components/AppIcon';
import { getLocalUrls } from '../../utils/mesaAcompanharUrl';
import RestauranteHeader from '../../components/restaurante/RestauranteHeader';

const NovoGarcomForm = ({ onCriado }) => {
  const [nome, setNome] = useState('');
  const [telefone, setTelefone] = useState('');
  const [senha, setSenha] = useState('');
  const [erro, setErro] = useState(null);
  const [salvando, setSalvando] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setErro(null);
    setSalvando(true);
    try {
      await criarGarcom({ nome, telefone, senha });
      setNome(''); setTelefone(''); setSenha('');
      onCriado();
    } catch (err) {
      setErro(err.message);
    } finally {
      setSalvando(false);
    }
  };

  return (
    <form onSubmit={submit} className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 mb-4 flex flex-wrap gap-2 items-end">
      <div className="flex-1 min-w-[140px]">
        <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Nome</label>
        <input value={nome} onChange={(e) => setNome(e.target.value)} required
          className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
      </div>
      <div className="flex-1 min-w-[140px]">
        <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Telefone</label>
        <input value={telefone} onChange={(e) => setTelefone(e.target.value)}
          className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
      </div>
      <div className="flex-1 min-w-[140px]">
        <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Senha inicial</label>
        <input value={senha} onChange={(e) => setSenha(e.target.value)} required minLength={4}
          className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
      </div>
      {erro && <p className="text-xs text-red-600 dark:text-red-400 w-full">{erro}</p>}
      <button type="submit" disabled={salvando}
        className="px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl disabled:opacity-50">
        {salvando ? 'Criando...' : 'Criar garçom'}
      </button>
    </form>
  );
};

const GarcomCard = ({ garcom, onMudou }) => {
  const [copiado, setCopiado] = useState(false);
  const [modo, setModo] = useState('online'); // 'online' | 'local'
  const urls = getLocalUrls(`/garcom/${garcom.login_key}`);
  const link = modo === 'local' && urls.lan ? urls.lan : urls.principal;

  const copiarLink = () => {
    navigator.clipboard?.writeText(link);
    setCopiado(true);
    setTimeout(() => setCopiado(false), 2000);
  };

  const togglePermissao = async (chave) => {
    // pagamento_parcial é default ligado (undefined = true) — as outras são default desligado.
    const atual = chave === 'pagamento_parcial' ? garcom.permissoes?.[chave] !== false : !!garcom.permissoes?.[chave];
    await atualizarGarcom(garcom.id, { permissoes: { ...garcom.permissoes, [chave]: !atual } });
    onMudou();
  };

  const toggleAtivo = async () => {
    await atualizarGarcom(garcom.id, { ativo: !garcom.ativo });
    onMudou();
  };

import React, { useState, useEffect, useCallback } from 'react';
import {
  listarMotoboys, listarSolicitacoesMotoboy, aceitarSolicitacaoMotoboy,
  recusarSolicitacaoMotoboy, revisarSolicitacaoMotoboy, removerAfiliacaoMotoboy,
} from '../../services/restauranteService';
import Icon from '../../components/AppIcon';
import RestauranteHeader from '../../components/restaurante/RestauranteHeader';

// Signed URL do Supabase carrega query string (?token=...) depois do nome do arquivo —
// preciso olhar o path antes do "?" pra saber a extensão real.
const isPdfUrl = (url) => /\.pdf(\?|$)/i.test(url ?? '');

const ArquivoPreview = ({ url, alt, className }) => {
  if (isPdfUrl(url)) {
    return (
      <a href={url} target="_blank" rel="noreferrer"
        className={`${className} flex flex-col items-center justify-center gap-1 text-red-500 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40`}>
        <Icon name="FileText" size={20} />
        <span className="text-[10px] font-semibold">Ver PDF</span>
      </a>
    );
  }
  return (
    <a href={url} target="_blank" rel="noreferrer" className={className}>
      <img src={url} alt={alt} className="w-full h-full object-cover" />
    </a>
  );
};

const FichaModal = ({ solicitacao, onFechar, onAceitar, onRecusar, processando, somenteLeitura = false }) => {
  const [motivo, setMotivo] = useState('');
  const [mostrarRecusa, setMostrarRecusa] = useState(false);
  const mb = solicitacao.motoboy;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4" onClick={onFechar}>
      <div className="bg-white dark:bg-[#27272A] rounded-2xl w-full max-w-md p-6 max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center gap-3 mb-5">
          <div className="w-16 h-16 rounded-2xl overflow-hidden bg-[#F4F4F5] dark:bg-[#3F3F46] flex-shrink-0">
            {mb.foto_perfil_url
              ? <ArquivoPreview url={mb.foto_perfil_url} alt={mb.name} className="block w-full h-full" />
              : <div className="w-full h-full flex items-center justify-center"><Icon name="User" size={24} className="text-[#A1A1AA]" /></div>}
          </div>
          <div>
            <h3 className="text-lg font-bold text-gray-900 dark:text-gray-400">{mb.name}</h3>
            <p className="text-sm text-gray-500 dark:text-gray-400">{mb.phone}</p>
            <p className="text-xs text-gray-400">{mb.email}</p>
          </div>
        </div>

        <div className="space-y-3">
          <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase">Documentos</p>
          <div className="grid grid-cols-2 gap-2">
            {mb.documento_frente_url && (
              <ArquivoPreview url={mb.documento_frente_url} alt="Documento frente"
                className="block rounded-xl overflow-hidden border border-gray-200 dark:border-gray-800 aspect-video bg-gray-50 dark:bg-gray-950/40" />
            )}
            {mb.documento_verso_url && (
              <ArquivoPreview url={mb.documento_verso_url} alt="Documento verso"
                className="block rounded-xl overflow-hidden border border-gray-200 dark:border-gray-800 aspect-video bg-gray-50 dark:bg-gray-950/40" />
            )}
          </div>
          {mb.comprovante_endereco_url && (
            <a href={mb.comprovante_endereco_url} target="_blank" rel="noreferrer"
              className="flex items-center gap-2 border border-gray-200 dark:border-gray-800 rounded-xl px-3 py-2.5 text-sm text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40">
              <Icon name="FileText" size={16} /> Ver comprovante de endereço
            </a>
          )}
        </div>

        {somenteLeitura ? (
          <button onClick={onFechar} className="w-full mt-5 py-2.5 border rounded-xl text-sm text-gray-700 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-950/40">
            Fechar
          </button>
        ) : mostrarRecusa ? (
          <div className="mt-5 space-y-2">
            <textarea value={motivo} onChange={(e) => setMotivo(e.target.value)} rows={3}
              placeholder="Motivo da recusa (opcional)"
              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-red-400 resize-none" />
            <div className="flex gap-2">

-- Módulo Salão: garçons (staff do restaurante, login próprio via key+senha, criado só pelo dono)
CREATE TABLE IF NOT EXISTS public.garcons (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  nome           TEXT NOT NULL,
  telefone       TEXT,
  login_key      TEXT NOT NULL UNIQUE,
  password_hash  TEXT NOT NULL,
  ativo          BOOLEAN NOT NULL DEFAULT true,
  permissoes     JSONB NOT NULL DEFAULT '{"desconto":false,"cancelar":false,"acrescimo":false}'::jsonb,
  ultimo_acesso_em TIMESTAMPTZ,
  created_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_garcons_restaurant ON public.garcons (restaurant_id);

ALTER TABLE public.garcons ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcons_owner ON public.garcons
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

-- Vincula o motoboy a uma conta de cliente (Supabase Auth), quando o cadastro de
-- motoboy é feito por alguém já logado como cliente. Usado pra promover
-- user_profiles.role pra 'motoboy' automaticamente nesse caso.
ALTER TABLE public.motoboys
  ADD COLUMN IF NOT EXISTS user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_motoboys_user_id ON public.motoboys (user_id) WHERE user_id IS NOT NULL;

